isVisible:
{{
  [
    Rating29.value,
    Rating30.value,
    Rating31.value,
    Rating32.value,
    Rating33.value,
    Rating34.value,
    Rating35.value,
    Rating36.value
  ].every(r => r >= 1)
}}

text:
{{
  (() => {
    const somma =
      Rating29.value +
      Rating30.value +
      Rating31.value +
      Rating32.value +
      Rating33.value +
      Rating34.value +
      Rating35.value +
      Rating36.value;

    return somma === 0 ? "" : (somma === 24 ? "IDONEO" : "NON IDONEO");
  })()
}}

textColor:
